/* eslint-disable */
/**
 * Firebase Cloud Messaging service worker — background notifications only.
 *
 * WHY THIS IS A SECOND, SEPARATE SERVICE WORKER
 * --------------------------------------------
 * The app already has a service worker: the Workbox one generated by vite-plugin-pwa, at
 * scope `/`. It is what makes offline reload work, and MERGE-PLAN.md records that it is
 * verified working on real hardware inside the installed PWA — and that a proposed change
 * to its registration was rejected as "risk for zero gain".
 *
 * This file does not touch it. Firebase registers this worker at its own narrow scope
 * (`/firebase-cloud-messaging-push-scope`), which does not collide with `/`. Two workers,
 * two scopes, no interaction.
 *
 * The alternative — switching vite-plugin-pwa to `strategies: 'injectManifest'` and
 * hand-writing a single merged worker — would mean re-verifying offline reload on a real
 * device to gain nothing. Not worth it before a deadline.
 *
 * WHY THIS FILE IS IN public/ AND USES importScripts
 * -------------------------------------------------
 * It must be served from the site root as a standalone script, so it cannot be part of the
 * module graph Vite bundles. That rules out `import` statements and means it cannot read
 * `import.meta.env`. The compat build loaded over importScripts is the supported way to do
 * this, and the config below is injected at build time by the small plugin in
 * vite.config.ts — see `firebaseMessagingSwPlugin`.
 *
 * A Firebase web config is not a secret; it identifies the project and ships in every
 * Firebase web app.
 */

importScripts('https://www.gstatic.com/firebasejs/12.17.1/firebase-app-compat.js');
importScripts('https://www.gstatic.com/firebasejs/12.17.1/firebase-messaging-compat.js');

// __FIREBASE_CONFIG__ is replaced at build time. Left as a literal placeholder when the
// feature is not configured, in which case initialisation is skipped entirely below.
const firebaseConfig = __FIREBASE_CONFIG__;

/**
 * Notification text, in the three languages the app supports.
 *
 * Duplicated here rather than imported from src/i18n/locales/*.json, and that is a real
 * trade-off worth naming: this file is outside the bundle, so it cannot import them. The
 * strings are kept few and stable to limit the cost, and `npm run check:i18n` does NOT
 * cover them — if the wording changes in the app, it must be changed here by hand.
 *
 * Rendering here rather than letting FCM display a `notification` payload is what makes a
 * Bengali doctor get a Bengali notification: the server does not know which language any
 * given recipient reads, so it sends data only and the language is chosen on the device.
 */
const STRINGS = {
  bn: {
    title: 'উচ্চ ঝুঁকির রোগী',
    body: (d) => `${d.patientName}, ${d.patientAge} — ${d.village || ''}`.trim().replace(/—\s*$/, ''),
    fallback: 'একজন উচ্চ ঝুঁকির রোগী চিহ্নিত হয়েছেন',
  },
  hi: {
    title: 'उच्च जोखिम वाला मरीज़',
    body: (d) => `${d.patientName}, ${d.patientAge} — ${d.village || ''}`.trim().replace(/—\s*$/, ''),
    fallback: 'एक उच्च जोखिम वाला मरीज़ चिह्नित हुआ है',
  },
  en: {
    title: 'High-risk patient flagged',
    body: (d) => `${d.patientName}, ${d.patientAge} — ${d.village || ''}`.trim().replace(/—\s*$/, ''),
    fallback: 'A high-risk patient has been flagged',
  },
};

/**
 * The language comes from the SERVER, in `data.language`.
 *
 * That is a deliberate choice over reading it on the device. A service worker has no
 * localStorage and no `document`, so it cannot see the app's own language preference; the
 * options were a cookie written purely for the worker to read back, or letting the server
 * say. The server already stores `language` on every user account, so it groups recipients
 * by language and sends one message per group — no cookie, no guessing, and it stays correct
 * when a doctor has two devices.
 *
 * Bengali is the fallback, matching the app's default for the target district.
 */
const DEFAULT_LANGUAGE = 'bn';

if (firebaseConfig && firebaseConfig.projectId) {
  firebase.initializeApp(firebaseConfig);
  const messaging = firebase.messaging();

  /**
   * Data-only messages arrive here. The worker MUST call showNotification itself —
   * otherwise Chrome eventually substitutes its own generic "this site was updated in the
   * background" notice, which is both useless and alarming.
   */
  messaging.onBackgroundMessage((payload) => {
    const data = payload.data || {};
    if (data.type !== 'high-risk') return;

    const language = data.language || DEFAULT_LANGUAGE;
    const strings = STRINGS[language] || STRINGS[DEFAULT_LANGUAGE];

    const body = data.patientName ? strings.body(data) : strings.fallback;

    return self.registration.showNotification(strings.title, {
      body,
      icon: '/icons/icon-192.png',
      badge: '/icons/icon-192.png',
      lang: language,
      /**
       * Tagging by assessment id means a case delivered twice replaces its own notification
       * instead of stacking two identical ones — the same de-duplication the dashboard does
       * for socket-delivered cases.
       */
      tag: `high-risk-${data.assessmentId || 'unknown'}`,
      // Requires a tap to dismiss. A PHC doctor is not watching the screen; that is the
      // entire reason this feature exists.
      requireInteraction: true,
      data: { url: data.url || '/dashboard', assessmentId: data.assessmentId },
    });
  });

  /** Focus an existing tab rather than opening a second dashboard. */
  self.addEventListener('notificationclick', (event) => {
    event.notification.close();
    const target = (event.notification.data && event.notification.data.url) || '/dashboard';

    event.waitUntil(
      self.clients.matchAll({ type: 'window', includeUncontrolled: true }).then((clientList) => {
        for (const client of clientList) {
          if ('focus' in client) {
            if ('navigate' in client) client.navigate(target).catch(() => undefined);
            return client.focus();
          }
        }
        return self.clients.openWindow(target);
      }),
    );
  });
}
